script:
/* ---------- CONFIG / ELEMENTS ---------- */
const employeeInfo = [
    { title: "Sr. No.", name: "sr_no" },
    { title: "Employee Name", name: "employee_name" },
    { title: "Country", name: "country" },
    { title: "Employee ID", name: "custom_employee_id" },
    { title: "Company Name", name: "company" },
    { title: "Designation", name: "designation" },
    { title: "Department", name: "department" },
    { title: "Reporting Head Name", name: "reporting_head_name" },
    { title: "Company Email", name: "company_email" },
    { title: "Contact Number", name: "employee_number" },
    { title: "HOD Name", name: "hod_name" },
    { title: "Region", name: "region" },
    { title: "Login Reminder Count", name: "login_reminder_count" },
    { title: "Course Reminder Count", name: "course_reminder_count" },
    { title: "Course Status", name: "completion_status" },
    { title: "Enrolment Version", name: "enrollment_version" },
    { title: "Course Completion Date & Time", name: "completed_on" },
    { title: "Progress", name: "progress" },
    { title: "Course Name", name: "course_name" },
    { title: "Send Initial Notification", name: "employee_user_id" },
    { title: "Course Timeline", name: "enrollment_history" }
];

const download_view_btn = root_element.querySelector("#download_view_btn");
if (download_view_btn) {
    download_view_btn.addEventListener("click", () => {
        frappe.set_route("query-report", "Employee Report");
    });
}

const table = root_element.querySelector('.employee_table');
const thead = table ? table.querySelector('thead') : null;
const heading_container = thead ? thead.querySelector('.heading_container') : null;
const employee_table_body = root_element.querySelector('.employee_table_body');
const rowsPerPageSelect = root_element.querySelector("#rowsPerPage");
const refreshButton = root_element.querySelector("#refresh");
const nextBtn = root_element.querySelector('.next_employee_page');
const prevBtn = root_element.querySelector('.prev_employee_page');
const pageInput = root_element.querySelector('.page_input');
const totalPagesSpan = root_element.querySelector('.total_pages');
const sortBySelect = root_element.querySelector('#sortBy');

let currentPage = 1;
let rowsPerPage = parseInt(rowsPerPageSelect ? rowsPerPageSelect.value : 5, 10) || 5;
let employeesData = [];
let filteredData = [];

/* ---------- LOADING & ERROR ELEMENTS ---------- */
const statusRow = document.createElement("tr");
statusRow.classList.add("status-row");

const statusCell = document.createElement("td");
statusCell.colSpan = employeeInfo.length;
statusCell.classList.add("text-center", "py-3", "fw-bold");
statusRow.appendChild(statusCell);

renderTitles();
setupSortOptions();
bindRowsPerPage();
bindPagination();
refreshButton && refreshButton.addEventListener("click", RefreshData);
RefreshData();

function renderTitles() {
    if (!heading_container || !thead) return;

    heading_container.innerHTML = '';
    employeeInfo.forEach(info => {
        const th = document.createElement('th');
        th.innerText = info.title;
        heading_container.appendChild(th);
    });

    const existing = thead.querySelector('.filter-row');
    if (existing) existing.remove();

    const filterRow = document.createElement('tr');
    filterRow.classList.add('filter-row');

    employeeInfo.forEach(info => {
        const fc = document.createElement('th');
        if (info.name !== 'sr_no') {
            const input = document.createElement('input');
            input.type = 'text';
            input.placeholder = 'Filter...';
            input.className = 'form-control form-control-sm column-filter';
            input.dataset.field = info.name;
            input.addEventListener('input', debounce(applyFilters, 200));
            fc.appendChild(input);
        }
        filterRow.appendChild(fc);
    });

    thead.appendChild(filterRow);
}

function setupSortOptions() {
    if (!sortBySelect) return;
    const sortOptions = [
        { label: "No Sorting", value: "" },
        { label: "Employee Name (A-Z)", value: "employee_name" },
        { label: "Company (A-Z)", value: "company" },
        { label: "Course Completion Date (Newest First)", value: "completed_on" },
        { label: "Progress (High-Low)", value: "progress" }
    ];
    sortBySelect.innerHTML = '';
    sortOptions.forEach(opt => {
        const option = document.createElement('option');
        option.value = opt.value;
        option.innerText = opt.label;
        sortBySelect.appendChild(option);
    });
    sortBySelect.addEventListener('change', () => {
        applySorting();
        currentPage = 1;
        renderCurrentPage();
    });
}

function bindRowsPerPage() {
    if (!rowsPerPageSelect) return;
    rowsPerPageSelect.addEventListener('change', () => {
        if (rowsPerPageSelect.value === 'All') {
            rowsPerPage = filteredData.length || 1;
        } else {
            rowsPerPage = parseInt(rowsPerPageSelect.value, 10) || 5;
        }
        currentPage = 1;
        renderCurrentPage();
    });
}

function bindPagination() {
    nextBtn && nextBtn.addEventListener('click', () => {
        const totalPages = getTotalPages();
        if (currentPage < totalPages) {
            currentPage += 1;
            renderCurrentPage();
        }
    });

    prevBtn && prevBtn.addEventListener('click', () => {
        if (currentPage > 1) {
            currentPage -= 1;
            renderCurrentPage();
        }
    });

    pageInput && pageInput.addEventListener('change', (e) => {
        let val = parseInt(e.target.value, 10) || 1;
        const totalPages = getTotalPages();
        if (val < 1) val = 1;
        if (val > totalPages) val = totalPages;
        currentPage = val;
        renderCurrentPage();
    });
}

/* ---------- DATA FETCH ---------- */
function RefreshData() {
    showStatus('Fetching data, please wait...', 'loading');

    frappe.call({
        method: "lms.overrides.dashboardapi.get_employee_dashboard_info",
        callback: (response) => {
            if (response.message) {
                employeesData = Array.isArray(response.message) ? response.message : [];
                filteredData = [...employeesData];
                if (rowsPerPageSelect && rowsPerPageSelect.value === 'All') {
                    rowsPerPage = filteredData.length || 1;
                }
                currentPage = 1;
                applySorting();
                renderCurrentPage();
            } else {
                showStatus('Error: No data returned from server', 'error');
            }
        },
        error: () => {
            showStatus('Error fetching data. Please try again.', 'error');
        }
    });
}

/* ---------- RENDER TABLE ---------- */
function renderCurrentPage() {
    if (!employee_table_body) return;

    employee_table_body.innerHTML = '';

    if (!filteredData.length) {
        const message = employeesData.length ? 'No employees match the selected filters.' : 'No employee records found.';
        showStatus(message, 'muted');
        updatePagination(1);
        return;
    }

    const totalPages = getTotalPages();
    const start = (currentPage - 1) * rowsPerPage;
    const end = start + rowsPerPage;

    filteredData.slice(start, end).forEach((employee, index) => {
        const srNo = start + index + 1;
        employee_table_body.appendChild(buildRow(employee, srNo));
    });

    updatePagination(totalPages);
}

function buildRow(employee, srNo) {
    const tr = document.createElement('tr');
    employeeInfo.forEach(info => {
        tr.appendChild(buildCell(info, employee, srNo));
    });
    return tr;
}

function buildCell(info, employee, srNo) {
    const cell = document.createElement('td');

    if (info.name === 'sr_no') {
        cell.innerText = srNo;
        return cell;
    }

    if (info.name === 'employee_name') {
        const btn = document.createElement('span');
        btn.innerText = employee.employee_name || '';
        btn.classList.add('employee_btn');
        cell.classList.add('link');
        cell.tabIndex = 0;
        const navigate = () => frappe.set_route('Form', 'Employee', employee.employee_docid);
        cell.addEventListener('click', navigate);
        cell.addEventListener('keydown', (event) => {
            if (event.code === 'Space' || event.code === 'Enter') {
                event.preventDefault();
                navigate();
            }
        });
        cell.appendChild(btn);
        return cell;
    }

    if (info.name === 'company_email') {
        const email = employee.company_email || '';
        if (email) {
            const link = document.createElement('a');
            link.href = `mailto:${email}`;
            link.innerText = email;
            link.classList.add('text-decoration-none');
            cell.appendChild(link);
        } else {
            cell.innerText = '-';
        }
        return cell;
    }

    if (info.name === 'employee_number') {
        cell.innerText = employee.employee_number || '-';
        return cell;
    }

    if (info.name === 'completion_status') {
        renderStatusCell(cell, employee);
        return cell;
    }

    if (info.name === 'progress') {
        renderProgressCell(cell, employee);
        return cell;
    }

    if (info.name === 'completed_on') {
        cell.innerText = employee.completed_on ? formatTime(employee.completed_on) : '-';
        return cell;
    }

    if (info.name === 'course_name') {
        cell.innerText = employee.course_name || '-';
        return cell;
    }

    if (info.name === 'reporting_head_name' || info.name === 'hod_name' || info.name === 'region') {
        cell.innerText = employee[info.name] || '-';
        return cell;
    }

    if (info.name === 'enrollment_version') {
        cell.innerText = employee.enrollment_version || '-';
        return cell;
    }

    if (info.name === 'login_reminder_count' || info.name === 'course_reminder_count') {
        cell.innerText = employee[info.name] ?? '0';
        return cell;
    }

    if (info.name === 'employee_user_id') {
        if (!employee[info.name]) {
            const btn = document.createElement('button');
            btn.innerText = 'Send Initial Notifications';
            btn.classList = 'btn btn-sm btn-primary';

            btn.addEventListener('click', () => {
                btn.disabled = true;
                btn.innerText = 'Sending...';

                frappe.call({
                    method: 'lms.lms.user.create_user_from_employee',
                    args: {
                        employee_id: employee.employee_docid,
                        _method: 'manual'
                    },
                    callback: function (r) {
                        if (!r.exc) {
                            frappe.show_alert({ message: 'User created & notifications sent!', indicator: 'green' });
                            RefreshData();
                        } else {
                            frappe.show_alert({ message: 'Error creating user', indicator: 'red' });
                            btn.disabled = false;
                            btn.innerText = 'Send Initial Notifications';
                        }
                    },
                    error: function (err) {
                        frappe.show_alert({ message: 'Server Error', indicator: 'red' });
                        console.error(err);
                        btn.disabled = false;
                        btn.innerText = 'Send Initial Notifications';
                    }
                });
            });

            cell.appendChild(btn);
        } else {
            const span = document.createElement('span');
            span.innerText = 'Sent';
            span.classList = 'badge bg-success text-white';
            cell.appendChild(span);
        }
        return cell;
    }

    if (info.name === 'enrollment_history') {
        cell.classList.add('timeline-cell');
        const history = Array.isArray(employee.enrollment_history)
            ? employee.enrollment_history
            : safeParseJSON(employee.enrollment_history);

        if (!history || history.length === 0) {
            cell.innerText = 'No enrollments';
            return cell;
        }

        // Filter to only show the enrollment matching this row's course and version
        const currentCourse = employee.course_name;
        const currentVersion = employee.enrollment_version;
        const filteredHistory = history.filter(entry =>
            entry.course === currentCourse &&
            entry.enrollment_version === currentVersion
        );

        if (filteredHistory.length === 0) {
            cell.innerText = 'No matching enrollment';
            return cell;
        }

        const timelineWrapper = document.createElement('div');
        timelineWrapper.className = 'timeline-wrapper';

        filteredHistory.forEach((entry, idx) => {
            const item = document.createElement('div');
            item.className = 'timeline-item';

            const header = document.createElement('div');
            header.className = 'timeline-header';
            header.innerText = `${entry.course || 'Course'} (v${entry.enrollment_version || 1})`;
            item.appendChild(header);

            const statusRow = document.createElement('div');
            statusRow.className = 'timeline-status';
            const statusBadge = document.createElement('span');
            statusBadge.className = `badge status-${(entry.completion_status || 'pending').toLowerCase().replace(/\s+/g, '-')}`;
            statusBadge.innerText = entry.completion_status || 'Pending';
            statusRow.appendChild(statusBadge);

            if (entry.progress !== null && entry.progress !== undefined) {
                const progressText = document.createElement('span');
                progressText.className = 'timeline-progress';
                progressText.innerText = `${entry.progress}%`;
                statusRow.appendChild(progressText);
            }

            if (entry.completed_on) {
                const completedText = document.createElement('span');
                completedText.className = 'timeline-date';
                completedText.innerText = formatTime(entry.completed_on);
                statusRow.appendChild(completedText);
            }

            item.appendChild(statusRow);

            if (entry.documents && entry.documents.length) {
                const docsRow = document.createElement('div');
                docsRow.className = 'timeline-documents';
                entry.documents.forEach(doc => {
                    const docBadge = document.createElement('span');
                    docBadge.className = 'badge document-badge';
                    docBadge.innerText = doc.name || 'Document';
                    const targetId = doc.docid || doc.name;
                    if (targetId) {
                        docBadge.classList.add('document-link');
                        docBadge.tabIndex = 0;
                        const go = () => frappe.set_route('Form', 'Employee Course Documents', targetId);
                        docBadge.addEventListener('click', go);
                        docBadge.addEventListener('keydown', (event) => {
                            if (event.code === 'Space' || event.keyCode === 32 || event.code === 'Enter' || event.keyCode === 13) {
                                event.preventDefault();
                                go();
                            }
                        });
                    } else if (doc.url) {
                        docBadge.classList.add('document-link');
                        docBadge.tabIndex = 0;
                        docBadge.addEventListener('click', () => {
                            window.open(doc.url, '_blank');
                        });
                        docBadge.addEventListener('keydown', (event) => {
                            if (event.code === 'Space' || event.keyCode === 32 || event.code === 'Enter' || event.keyCode === 13) {
                                event.preventDefault();
                                window.open(doc.url, '_blank');
                            }
                        });
                    }
                    docsRow.appendChild(docBadge);
                });
                item.appendChild(docsRow);
            }

            timelineWrapper.appendChild(item);
        });

        cell.appendChild(timelineWrapper);
        return cell;
    }

    cell.innerText = employee[info.name] ?? '';
    return cell;
}

function renderStatusCell(cell, employee) {
    const statusRaw = (employee.completion_status || '').trim().toLowerCase();
    const docId = employee.docuemnts_id;

    if (statusRaw === 'completed') {
        const badge = document.createElement('span');
        badge.className = 'badge bg-success text-white me-2';
        badge.innerText = 'Completed';
        cell.appendChild(badge);
        if (docId) {
            cell.classList.add('link');
            cell.tabIndex = 0;
            const goToDoc = () => frappe.set_route('Form', 'Employee Course Documents', docId);
            cell.addEventListener('click', goToDoc);
            cell.addEventListener('keydown', (event) => {
                if (event.code === 'Space' || event.code === 'Enter') {
                    event.preventDefault();
                    goToDoc();
                }
            });
        }
        if (employee.completed_on) {
            const dateSpan = document.createElement('div');
            dateSpan.className = 'text-muted small';
            dateSpan.innerText = formatTime(employee.completed_on);
            cell.appendChild(dateSpan);
        }
        return;
    }

    if (statusRaw === 'active' || statusRaw === 're-enrolled') {
        const badge = document.createElement('span');
        badge.className = 'badge bg-warning text-white text-uppercase';
        badge.innerText = statusRaw;
        cell.appendChild(badge);
        return;
    }

    const badge = document.createElement('span');
    badge.className = 'badge bg-secondary text-white';
    badge.innerText = 'Pending';
    cell.appendChild(badge);
}

function renderProgressCell(cell, employee) {
    const progressValue = Math.max(0, Math.min(100, Math.round(Number(employee.progress) || 0)));
    const wrapper = document.createElement('div');
    wrapper.className = 'progress-wrapper d-flex align-items-center';

    const progress = document.createElement('progress');
    progress.className = 'styled-progress me-2';
    progress.max = 100;
    progress.value = progressValue;

    const text = document.createElement('span');
    text.className = 'progress-text fw-bold';
    text.innerText = `${progressValue}%`;

    wrapper.appendChild(progress);
    wrapper.appendChild(text);
    cell.appendChild(wrapper);
}

function updatePagination(totalPages) {
    if (totalPagesSpan) {
        totalPagesSpan.innerText = totalPages;
    }
    if (pageInput) {
        pageInput.max = totalPages;
        pageInput.value = Math.min(currentPage, totalPages);
    }
}

function getTotalPages() {
    if (!filteredData.length) {
        return 1;
    }
    return Math.max(1, Math.ceil(filteredData.length / rowsPerPage));
}

/* ---------- FILTERS & SORT ---------- */
function applyFilters() {
    if (!employeesData.length) return;
    const inputs = Array.from(root_element.querySelectorAll('.column-filter'));
    const filters = {};
    inputs.forEach(inp => {
        const value = inp.value.trim().toLowerCase();
        if (value) {
            filters[inp.dataset.field] = value;
        }
    });

    filteredData = employeesData.filter(employee => {
        return Object.keys(filters).every(field => {
            const searchVal = getSearchableValue(employee, field);
            return searchVal.includes(filters[field]);
        });
    });

    applySorting();
    currentPage = 1;
    renderCurrentPage();
}

function applySorting() {
    if (!sortBySelect) return;
    const sortKey = sortBySelect.value;
    if (!sortKey) return;

    filteredData.sort((a, b) => {
        if (sortKey === 'employee_name' || sortKey === 'company') {
            const A = (a[sortKey] || '').toString().toLowerCase();
            const B = (b[sortKey] || '').toString().toLowerCase();
            return A.localeCompare(B);
        }
        if (sortKey === 'completed_on') {
            const da = new Date(a.completed_on || 0).getTime();
            const db = new Date(b.completed_on || 0).getTime();
            return db - da;
        }
        if (sortKey === 'progress') {
            return (Number(b.progress) || 0) - (Number(a.progress) || 0);
        }
        return 0;
    });
}

function getSearchableValue(row, field) {
    if (!row) return '';
    if (field === 'employee_number') {
        return (row.employee_number || '').toString().toLowerCase();
    }
    if (field === 'completion_status') {
        const status = (row.completion_status || '').toLowerCase();
        const date = formatTime(row.completed_on || '') || '';
        return `${status} ${date}`.trim().toLowerCase();
    }
    if (field === 'completed_on') {
        return (formatTime(row.completed_on) || '').toLowerCase();
    }
    if (field === 'progress') {
        return `${row.progress || 0}`;
    }
    return (row[field] || '').toString().toLowerCase();
}

/* ---------- HELPERS ---------- */
function safeParseJSON(data) {
    if (!data) return null;
    if (Array.isArray(data)) return data;
    try {
        return JSON.parse(data);
    } catch (e) {
        console.warn('Failed to parse JSON:', e, data);
        return null;
    }
}

function debounce(fn, wait) {
    let timeout;
    return function (...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => fn.apply(this, args), wait);
    };
}

function showStatus(message, type = 'loading') {
    if (!employee_table_body) return;
    employee_table_body.innerHTML = '';
    statusCell.innerText = message;

    statusCell.classList.remove('text-danger', 'text-primary', 'text-muted');
    if (type === 'error') {
        statusCell.classList.add('text-danger');
    } else if (type === 'loading') {
        statusCell.classList.add('text-primary');
    } else {
        statusCell.classList.add('text-muted');
    }

    employee_table_body.appendChild(statusRow);
}

function formatTime(datetimeStr) {
    if (!datetimeStr) return '';
    const base = String(datetimeStr).split('.')[0].replace(' ', 'T');
    const date = new Date(base);
    if (Number.isNaN(date.getTime())) return String(datetimeStr);
    const monthNames = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
    ];
    const month = monthNames[date.getMonth()];
    const day = String(date.getDate()).padStart(2, '0');
    const year = date.getFullYear();
    let hours = date.getHours();
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;
    hours = String(hours).padStart(2, '0');
    return `${day} ${month} ${year} ${hours}:${minutes} ${ampm}`;
}

