    padding: 8px 12px;
    min-width: 220px;
    background: #fff;
    box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.02);
}

.timeline-header {
    font-weight: 600;
    margin-bottom: 4px;
    font-size: 13px;
}

.timeline-status {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
}

.timeline-progress {
    font-size: 12px;
    color: #111827;
    font-weight: 600;
}

.timeline-date {
    font-size: 11px;
    color: #6b7280;
}

.timeline-documents {
    margin-top: 6px;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.badge.status-completed {
    background-color: #16a34a;
    color: #fff;
}

.badge.status-active, .badge.status-re-enrolled, .badge.status-active {
    background-color: #f59e0b;
    color: #fff;
}

.badge.status-pending {
    background-color: #6b7280;
    color: #fff;
}

.document-badge {
    background-color: #2563eb;
    color: #fff;
    cursor: default;
}

.document-badge.document-link {
    cursor: pointer;
}

.timeline-cell {
    max-width: 480px;
}
